"""`nexus --config`, the setup tool since config-tools went: how nexus hands it over, the checkout it sets up
(AGENTS_DIR, as nexus reads it), and the files config-tools wrote before, which stay in step until the next
writing run writes them anew."""
import os
import shutil

from scen import NO_LINK, case, two_personas

# What config-tools wrote, before it was `nexus --config`: the generated file's header and grok comment, and
# the header of a grok persona's config.
LEGACY_COMPOSE = (
    ("# compose.personas.yml — generated by nexus --config from personas.json; don't edit it. Re-run\n"
     "# nexus --config to add, change or remove personas: nexus won't create a container from a file that\n",
     "# compose.personas.yml — generated by ./config-tools from personas.json; don't edit it. Re-run\n"
     "# config-tools to add, change or remove personas: nexus won't create a container from a file that\n"),
    ("written by nexus --config: personas/grok.toml", "written by config-tools: personas/grok.toml"),
)
LEGACY_GROK = (   # its header, and the comments of personas/grok.toml and statusline/grok/settings.toml in it
    ("nexus --config", "config-tools"),
)


def as_config_tools_wrote_it(sb, rel, subs):
    p = sb.path(rel)
    with open(p) as f:
        text = f.read()
    for now, then in subs:
        if now not in text:
            raise RuntimeError("%s: no %r in it" % (rel, now))
        text = text.replace(now, then)
    with open(p, "w") as f:
        f.write(text)


@case("config/cfg-route")
def _(sb):
    # nexus hands --config, as its first argument, to the setup tool: its usage, its errors (config: …), its
    # --list; anything else that starts with - is no persona.
    sb.run("nexus", "--config", "--help")
    sb.run("nexus", "--config", "--bogus")
    sb.run("nexus", "--config", "--list", label="nexus --config --list  (nothing set up)")
    sb.run("nexus", "--configure")
    sb.personas("c1:claude:docker")
    sb.run("nexus", "--config", "--list")
    sb.run("nexus", "--configure")
    sb.run("nexus", "ls", "--config")


@case("config/cfg-agents-dir")
def _(sb):
    # AGENTS_DIR names the checkout nexus works on, and so the one `nexus --config` sets up: by name, a
    # relative one from this directory; this checkout's own files stay as they are.
    shutil.copytree(sb.a, sb.path("b"), symlinks=True)
    b = {"AGENTS_DIR": sb.path("b")}
    sb.run("nexus", "--config", "--yes", *NO_LINK, "--projects-root", sb.projects, "--persona", "c1:claude:docker",
           env=b, label="nexus --config --yes … --persona c1:claude:docker  (AGENTS_DIR=<S>/b)")
    sb.run("nexus", "--config", "--list", env=b, label="nexus --config --list  (AGENTS_DIR=<S>/b)")
    sb.run("nexus", "ls", env=b, label="nexus ls  (AGENTS_DIR=<S>/b)")
    sb.run("nexus", "--config", "--list", env={"AGENTS_DIR": "../b"}, label="nexus --config --list  (AGENTS_DIR=../b)")
    sb.run("nexus", "--config", "--list", label="nexus --config --list  (its own checkout)")
    sb.run("nexus", "--config", "--list", env={"AGENTS_DIR": sb.path("nope")},
           label="nexus --config --list  (AGENTS_DIR=<S>/nope)")
    sb.run("nexus", "--config", "--help", env={"AGENTS_DIR": sb.path("nope")},
           label="nexus --config --help  (AGENTS_DIR=<S>/nope: the usage all the same)")
    # A directory, but no checkout: refused, nothing written there.
    sb.write("emptydir/.keep", "")
    sb.run("nexus", "--config", "--yes", *NO_LINK, "--persona", "c1:claude:docker", env={"AGENTS_DIR": sb.path("emptydir")},
           label="nexus --config --yes … --persona c1:claude:docker  (AGENTS_DIR=<S>/emptydir)")
    sb.run("nexus", "--config", "--list", env={"AGENTS_DIR": sb.path("emptydir")},
           label="nexus --config --list  (AGENTS_DIR=<S>/emptydir)")
    # Through a link to it: the checkout as it is, so the launcher there is found to be this one.
    sb.symlink("link-to-b", sb.path("b"))
    sb.write("lbin/.keep", "")
    sb.symlink("lbin/nexus", sb.path("b/nexus"))
    sb.run("nexus", "--config", "--yes", "--no-build", "--link", sb.path("lbin"), env={"AGENTS_DIR": sb.path("link-to-b")},
           label="nexus --config --yes --no-build --link <S>/lbin  (AGENTS_DIR=<S>/link-to-b, linked there already)")


@case("nexus/cfg-legacy-header")
def _(sb):
    # A compose.personas.yml config-tools wrote, before it was `nexus --config` (only its comments name it):
    # in step, so a git pull alone stops nothing.
    two_personas(sb)
    as_config_tools_wrote_it(sb, "a/compose.personas.yml", LEGACY_COMPOSE)
    sb.run("nexus", "c1", "start")
    sb.run("nexus", "g1", "start")


@case("config/cfg-legacy-grok")
def _(sb):
    # The next writing run writes the files config-tools wrote as they are now: their comments only, so no
    # persona is told to restart, and grok's settings haven't changed.
    two_personas(sb)
    as_config_tools_wrote_it(sb, "a/compose.personas.yml", LEGACY_COMPOSE)
    as_config_tools_wrote_it(sb, "a/personas/g1.grok.toml", LEGACY_GROK)
    sb.run("config", "--yes", *NO_LINK)
    sb.run("nexus", "g1", "start")
